(function() {
    'use strict';

    class CoopLeaderAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'CoopLeader \u2014 Credit Union Management';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    titleKey: 'round1_title',
                    descKey: 'round1_desc',
                    input1: { labelKey: 'r1_input1_label', hintKey: 'r1_input1_hint', min: 5, max: 25, value: 10 },
                    input2: { labelKey: 'r1_input2_label', hintKey: 'r1_input2_hint', min: 5, max: 30, value: 10 },
                    select: {
                        labelKey: 'r1_select_label',
                        hintKey: 'r1_select_hint',
                        options: [
                            { value: '1', labelKey: 'r1_opt1' },
                            { value: '2', labelKey: 'r1_opt2' },
                            { value: '3', labelKey: 'r1_opt3' }
                        ]
                    }
                },
                {
                    titleKey: 'round2_title',
                    descKey: 'round2_desc',
                    input1: { labelKey: 'r2_input1_label', hintKey: 'r2_input1_hint', min: 8, max: 24, value: 14 },
                    input2: { labelKey: 'r2_input2_label', hintKey: 'r2_input2_hint', min: 100, max: 2000, value: 500 },
                    select: {
                        labelKey: 'r2_select_label',
                        hintKey: 'r2_select_hint',
                        options: [
                            { value: '1', labelKey: 'r2_opt1' },
                            { value: '2', labelKey: 'r2_opt2' },
                            { value: '3', labelKey: 'r2_opt3' }
                        ]
                    }
                },
                {
                    titleKey: 'round3_title',
                    descKey: 'round3_desc',
                    input1: { labelKey: 'r3_input1_label', hintKey: 'r3_input1_hint', min: 200, max: 3000, value: 800 },
                    input2: { labelKey: 'r3_input2_label', hintKey: 'r3_input2_hint', min: 30, max: 100, value: 70 },
                    select: {
                        labelKey: 'r3_select_label',
                        hintKey: 'r3_select_hint',
                        options: [
                            { value: '1', labelKey: 'r3_opt1' },
                            { value: '2', labelKey: 'r3_opt2' },
                            { value: '3', labelKey: 'r3_opt3' }
                        ]
                    }
                },
                {
                    titleKey: 'round4_title',
                    descKey: 'round4_desc',
                    input1: { labelKey: 'r4_input1_label', hintKey: 'r4_input1_hint', min: 0, max: 5000, value: 1000 },
                    input2: { labelKey: 'r4_input2_label', hintKey: 'r4_input2_hint', min: 1, max: 7, value: 3 },
                    select: {
                        labelKey: 'r4_select_label',
                        hintKey: 'r4_select_hint',
                        options: [
                            { value: '1', labelKey: 'r4_opt1' },
                            { value: '2', labelKey: 'r4_opt2' },
                            { value: '3', labelKey: 'r4_opt3' }
                        ]
                    }
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cashReserves: 8000000,
                    loanPortfolio: 45000000,
                    nplRatio: 12.0,
                    efficiencyRatio: 89.0,
                    memberCount: 12000,
                    memberSatisfaction: 65,
                    capitalAdequacy: 8.0,
                    financialHealth: 45,
                    socialImpact: 60,
                    coopScore: 0,
                    lastEvent: '',
                    financialHealthHistory: [],
                    socialImpactHistory: [],
                    coopScoreHistory: [],
                    checkpoints: {}, // per-round pre-state snapshots for idempotent re-entry (v1.1.0)
                    eventRolls: {}   // persisted crisis-event rolls so replays are deterministic (v1.1.0)
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    numeric1: 10,
                    numeric2: 10,
                    strategy: 2
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var input1 = document.getElementById('numericInput1');
            var input2 = document.getElementById('numericInput2');
            var sel = document.getElementById('strategySelect');
            if (input1) decisions.numeric1 = parseFloat(input1.value);
            if (input2) decisions.numeric2 = parseFloat(input2.value);
            if (sel) decisions.strategy = parseInt(sel.value);

            var currentState = window.mySimulation.state;
            var idx = Math.min((currentState.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            if (isNaN(decisions.numeric1) || decisions.numeric1 < round.input1.min || decisions.numeric1 > round.input1.max) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('input1_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.numeric2) || decisions.numeric2 < round.input2.min || decisions.numeric2 > round.input2.max) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('input2_warning'), 'warning'
                );
                return false;
            }
            this._updateBriefing(currentState);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var event = '';
            var results = {};

            // --- Idempotency guard (v1.1.0): checkpoint the pre-round state on first entry,
            //     restore it on any re-entry (double-submit / Undo+resubmit) so the many
            //     scalar mutations and the three history pushes never compound. ---
            ds.checkpoints = ds.checkpoints || {};
            if (ds.checkpoints[period]) {
                this._restore(ds, ds.checkpoints[period], period);
            } else {
                ds.checkpoints[period] = this._snapshot(ds);
            }

            // --- Deterministic, persisted crisis-event roll: roll once per period and reuse it
            //     (was a live Math.random() re-rolled on every call -> non-reproducible). ---
            ds.eventRolls = ds.eventRolls || {};
            if (ds.eventRolls[period] === undefined) {
                ds.eventRolls[period] = Math.random();
            }
            var eventRoll = ds.eventRolls[period];

            if (period === 1) {
                var provisionCost = ds.loanPortfolio * (d.numeric1 / 100) * 0.12;
                ds.cashReserves -= provisionCost;

                var effImprove = d.numeric2 * 0.35;
                ds.efficiencyRatio = Math.max(55, ds.efficiencyRatio - effImprove);

                var nplReduce = (d.strategy * 1.8) + (d.numeric1 * 0.15);
                ds.nplRatio = Math.max(2, ds.nplRatio - nplReduce);

                if (d.strategy === 3) {
                    ds.memberSatisfaction -= 8;
                    ds.memberCount -= 300;
                } else if (d.strategy === 1) {
                    ds.memberSatisfaction += 3;
                }

                ds.capitalAdequacy += d.numeric1 * 0.2;

                if (eventRoll < 0.5) {
                    event = window.mySimulation.t('event_drought');
                    ds.nplRatio += 3;
                    ds.memberSatisfaction -= 5;
                }

                var finGain = (d.numeric1 * 1.2) + effImprove - (ds.nplRatio > 10 ? 5 : 0);
                var socChange = d.strategy === 1 ? 5 : (d.strategy === 2 ? 0 : -8);
                ds.financialHealth = Math.min(100, Math.max(0, ds.financialHealth + finGain));
                ds.socialImpact = Math.min(100, Math.max(0, ds.socialImpact + socChange));

                results = {
                    period: period,
                    provisionCost: Math.round(provisionCost),
                    nplRatio: Math.round(ds.nplRatio * 10) / 10,
                    efficiencyRatio: Math.round(ds.efficiencyRatio * 10) / 10,
                    financialHealth: Math.round(ds.financialHealth),
                    socialImpact: Math.round(ds.socialImpact),
                    cashReserves: Math.round(ds.cashReserves),
                    memberCount: ds.memberCount
                };

            } else if (period === 2) {
                var nim = d.numeric1 - 6;
                var intIncome = ds.loanPortfolio * (nim / 100);
                ds.cashReserves += intIncome;

                var modBudget = d.numeric2 * 1000;
                ds.cashReserves -= modBudget;

                var rateAttract = Math.max(0, (18 - d.numeric1) * 80);
                ds.memberCount += rateAttract;

                var modImpact = (d.numeric2 / 2000) * 12;
                ds.socialImpact = Math.min(100, ds.socialImpact + modImpact);
                ds.nplRatio = Math.max(2, ds.nplRatio - (d.numeric2 / 500));

                var ftCost = 0;
                if (d.strategy === 1) {
                    ds.memberCount -= 500;
                    ds.memberSatisfaction -= 5;
                } else if (d.strategy === 2) {
                    ftCost = 800000;
                    ds.cashReserves -= ftCost;
                    ds.memberCount += 200;
                    ds.memberSatisfaction += 3;
                    ds.efficiencyRatio -= 2;
                } else if (d.strategy === 3) {
                    ftCost = 1500000;
                    ds.cashReserves -= ftCost;
                    ds.memberCount += 600;
                    ds.memberSatisfaction += 5;
                    ds.efficiencyRatio -= 4;
                }

                if (eventRoll < 0.4) {
                    event = window.mySimulation.t('event_regulatory');
                    ds.capitalAdequacy -= 2;
                    ds.cashReserves -= 500000;
                }

                ds.financialHealth = Math.min(100, Math.max(0, ds.financialHealth + (nim * 1.5) - (d.numeric1 < 10 ? 5 : 0)));
                ds.socialImpact = Math.min(100, Math.max(0, ds.socialImpact + (rateAttract > 400 ? 5 : 0)));

                results = {
                    period: period,
                    interestIncome: Math.round(intIncome),
                    modificationBudget: Math.round(modBudget),
                    fintechCost: ftCost,
                    nplRatio: Math.round(ds.nplRatio * 10) / 10,
                    financialHealth: Math.round(ds.financialHealth),
                    socialImpact: Math.round(ds.socialImpact),
                    cashReserves: Math.round(ds.cashReserves),
                    memberCount: ds.memberCount
                };

            } else if (period === 3) {
                var techCost = d.numeric1 * 1000;
                ds.cashReserves -= techCost;

                var techEff = (d.numeric1 / 3000) * 12;
                var branchSav = ((100 - d.numeric2) / 100) * 8;
                ds.efficiencyRatio = Math.max(55, ds.efficiencyRatio - techEff - branchSav);

                var branchImpact = d.numeric2 < 60 ? -10 : (d.numeric2 < 80 ? -3 : 2);
                ds.socialImpact = Math.min(100, Math.max(0, ds.socialImpact + branchImpact));

                if (d.numeric2 < 50) {
                    ds.memberCount -= 800;
                    ds.memberSatisfaction -= 10;
                } else if (d.numeric2 < 70) {
                    ds.memberCount -= 200;
                    ds.memberSatisfaction -= 3;
                }

                if (d.strategy === 1) {
                    ds.efficiencyRatio -= 1;
                    ds.memberSatisfaction += 2;
                } else if (d.strategy === 2) {
                    ds.efficiencyRatio -= 5;
                    ds.memberSatisfaction -= 3;
                    ds.memberCount -= 200;
                    ds.socialImpact -= 3;
                } else if (d.strategy === 3) {
                    ds.efficiencyRatio -= 3;
                    ds.memberSatisfaction += 4;
                    ds.memberCount += 100;
                    ds.socialImpact += 2;
                }

                if (eventRoll < 0.45) {
                    event = window.mySimulation.t('event_fintech');
                    ds.memberCount += 300;
                    ds.cashReserves -= 200000;
                }

                ds.financialHealth = Math.min(100, Math.max(0, ds.financialHealth + techEff + branchSav));

                results = {
                    period: period,
                    techInvestment: Math.round(techCost),
                    efficiencyRatio: Math.round(ds.efficiencyRatio * 10) / 10,
                    branchRetention: d.numeric2,
                    financialHealth: Math.round(ds.financialHealth),
                    socialImpact: Math.round(ds.socialImpact),
                    cashReserves: Math.round(ds.cashReserves),
                    memberCount: ds.memberCount
                };

            } else {
                var benefitCost = d.numeric1 * 1000;

                if (d.strategy === 1) {
                    ds.socialImpact += 5;
                    ds.memberSatisfaction += 5;
                    ds.financialHealth -= 3;
                } else if (d.strategy === 2) {
                    ds.cashReserves -= benefitCost;
                    ds.cashReserves += 3000000;
                    ds.loanPortfolio += 15000000;
                    ds.memberCount += 4000;
                    var govProt = d.numeric2 / 7;
                    ds.socialImpact += Math.round(govProt * 8);
                    ds.financialHealth += 8;
                    ds.efficiencyRatio -= 5;
                    ds.memberSatisfaction += (d.numeric2 >= 4 ? 3 : -3);
                } else {
                    ds.cashReserves -= benefitCost;
                    ds.cashReserves += 8000000;
                    ds.loanPortfolio += 35000000;
                    ds.memberCount += 8000;
                    ds.efficiencyRatio -= 10;
                    ds.financialHealth += 15;
                    ds.socialImpact -= (7 - d.numeric2) * 3;
                    ds.memberSatisfaction -= (7 - d.numeric2) * 2;
                }

                if (eventRoll < 0.5) {
                    event = window.mySimulation.t('event_board');
                    ds.memberSatisfaction -= 5;
                    ds.socialImpact -= 3;
                }

                ds.socialImpact += (d.numeric1 / 5000) * 8;

                results = {
                    period: period,
                    mergerStance: d.strategy === 1 ? 'Reject' : (d.strategy === 2 ? 'Negotiate' : 'Accept'),
                    benefitFund: Math.round(benefitCost),
                    governanceSeats: d.numeric2,
                    financialHealth: Math.round(ds.financialHealth),
                    socialImpact: Math.round(ds.socialImpact),
                    cashReserves: Math.round(ds.cashReserves),
                    memberCount: ds.memberCount
                };
            }

            ds.memberSatisfaction = Math.max(0, Math.min(100, ds.memberSatisfaction));
            ds.financialHealth = Math.max(0, Math.min(100, Math.round(ds.financialHealth)));
            ds.socialImpact = Math.max(0, Math.min(100, Math.round(ds.socialImpact)));
            ds.nplRatio = Math.max(1, Math.round(ds.nplRatio * 10) / 10);
            ds.efficiencyRatio = Math.max(50, Math.round(ds.efficiencyRatio * 10) / 10);
            ds.capitalAdequacy = Math.max(4, Math.round(ds.capitalAdequacy * 10) / 10);

            ds.coopScore = Math.round(
                ds.financialHealth * 0.4 +
                ds.socialImpact * 0.35 +
                ds.memberSatisfaction * 0.15 +
                (Math.min(ds.financialHealth, ds.socialImpact) / 10) * 10 * 0.10
            );

            ds.financialHealthHistory.push(ds.financialHealth);
            ds.socialImpactHistory.push(ds.socialImpact);
            ds.coopScoreHistory.push(ds.coopScore);
            ds.lastEvent = event;

            results.coopScore = ds.coopScore;
            results.financialHealth = ds.financialHealth;
            results.socialImpact = ds.socialImpact;

            var eventAlert = document.getElementById('eventAlert');
            var eventText = document.getElementById('eventText');
            if (event && eventAlert && eventText) {
                eventText.innerHTML = event;
                eventAlert.style.display = 'block';
            } else if (eventAlert) {
                eventAlert.style.display = 'none';
            }

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cashReserves',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('nplDisplay', 'domainState.nplRatio',
                function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('efficiencyDisplay', 'domainState.efficiencyRatio',
                function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('membersDisplay', 'domainState.memberCount',
                function(v) { return Math.round(v).toLocaleString(); });
            uiManager.bind('finScoreDisplay', 'domainState.financialHealth');
            uiManager.bind('socScoreDisplay', 'domainState.socialImpact');
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Financial Health',
                                data: [],
                                borderColor: '#2e86c1',
                                backgroundColor: 'rgba(46,134,193,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'Social Impact',
                                data: [],
                                borderColor: '#27ae60',
                                backgroundColor: 'rgba(39,174,96,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'CoopScore',
                                data: [],
                                borderColor: '#f39c12',
                                backgroundColor: 'rgba(243,156,18,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Dual Scorecard Performance' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100 }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.financialHealthHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.financialHealthHistory },
                        { data: state.domainState.socialImpactHistory },
                        { data: state.domainState.coopScoreHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var finalFin = last.results ? last.results.financialHealth : 0;
            var finalSoc = last.results ? last.results.socialImpact : 0;
            var finalScore = last.results ? last.results.coopScore : 0;

            var performance = 'Needs Improvement';
            if (finalScore >= 70) performance = 'Good Cooperative Leader';
            if (finalScore >= 80) performance = 'Excellent Cooperative Leader';
            if (finalScore >= 90) performance = 'Outstanding Cooperative Leader';

            var insights = [];
            if (finalFin > finalSoc + 20) {
                insights.push('Financial focus was strong but social mission was underserved. In cooperatives, both dimensions must advance together.');
            } else if (finalSoc > finalFin + 20) {
                insights.push('Social mission was prioritized but financial sustainability suffered. Without financial health, the cooperative cannot serve members long-term.');
            } else {
                insights.push('Good balance between financial health and social impact \u2014 the hallmark of excellent cooperative management.');
            }

            return {
                coopScore: finalScore,
                financialHealth: finalFin,
                socialImpact: finalSoc,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var ds = state.domainState;
            if (ds.financialHealth < 40) return window.mySimulation.t('hint_fin_low');
            if (ds.socialImpact < 40) return window.mySimulation.t('hint_soc_low');
            if (ds.nplRatio > 10) return window.mySimulation.t('hint_npl_high');
            if (ds.efficiencyRatio > 80) return window.mySimulation.t('hint_efficiency_high');
            if (Math.abs(ds.financialHealth - ds.socialImpact) > 20) return window.mySimulation.t('hint_imbalance');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.period', label: 'Round', i18nKey: 'col_round' },
                { key: 'results.financialHealth', label: 'Fin. Health', i18nKey: 'col_fin_health' },
                { key: 'results.socialImpact', label: 'Social Impact', i18nKey: 'col_soc_impact' },
                { key: 'results.coopScore', label: 'CoopScore', i18nKey: 'col_coop_score' },
